-- ============================================================================
-- AI Operations — Central Agent Registry — live seed (Phase 2 Prompt 03).
--
-- Idempotent import of the 76 demo agents (16 core/shared + 60 site-specific)
-- into `ai_operations_agents`. `agent_key` is the stable application
-- identifier (unique) and is used for upsert, so re-running this migration
-- never duplicates rows. `site_id` is resolved from the live `ai_sites`
-- registry via `site_key` subqueries; group/shared agents keep `site_id = NULL`.
--
-- Safety:
--   * No secrets / credentials are imported — only safe metadata + reference
--     strings (model references are "Provider / Model" labels, never keys).
--   * `current_run_id` is intentionally left NULL (demo run ids are not real
--     UUIDs and are not linked live yet).
--   * `is_active = true` for all real registry entries (paused/disabled agents
--     remain visible; their `status` field captures the state). The Prompt-01
--     TEST/SANDBOX seed keeps `is_active = false` and is unaffected here.
-- ============================================================================

ON CONFLICT (agent_key) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, agent_type=EXCLUDED.agent_type, category=EXCLUDED.category, site_id=EXCLUDED.site_id, environment=EXCLUDED.environment, status=EXCLUDED.status, health=EXCLUDED.health, risk_level=EXCLUDED.risk_level, autonomy_level=EXCLUDED.autonomy_level, owner_team=EXCLUDED.owner_team, escalation_team=EXCLUDED.escalation_team, primary_model_reference=EXCLUDED.primary_model_reference, fallback_model_reference=EXCLUDED.fallback_model_reference, prompt_version_reference=EXCLUDED.prompt_version_reference, current_task=EXCLUDED.current_task, queue_count=EXCLUDED.queue_count, success_rate=EXCLUDED.success_rate, notes=EXCLUDED.notes, is_active=EXCLUDED.is_active;

ON CONFLICT (agent_key) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, agent_type=EXCLUDED.agent_type, category=EXCLUDED.category, site_id=EXCLUDED.site_id, environment=EXCLUDED.environment, status=EXCLUDED.status, health=EXCLUDED.health, risk_level=EXCLUDED.risk_level, autonomy_level=EXCLUDED.autonomy_level, owner_team=EXCLUDED.owner_team, escalation_team=EXCLUDED.escalation_team, primary_model_reference=EXCLUDED.primary_model_reference, fallback_model_reference=EXCLUDED.fallback_model_reference, prompt_version_reference=EXCLUDED.prompt_version_reference, current_task=EXCLUDED.current_task, queue_count=EXCLUDED.queue_count, success_rate=EXCLUDED.success_rate, notes=EXCLUDED.notes, is_active=EXCLUDED.is_active;

ON CONFLICT (agent_key) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, agent_type=EXCLUDED.agent_type, category=EXCLUDED.category, site_id=EXCLUDED.site_id, environment=EXCLUDED.environment, status=EXCLUDED.status, health=EXCLUDED.health, risk_level=EXCLUDED.risk_level, autonomy_level=EXCLUDED.autonomy_level, owner_team=EXCLUDED.owner_team, escalation_team=EXCLUDED.escalation_team, primary_model_reference=EXCLUDED.primary_model_reference, fallback_model_reference=EXCLUDED.fallback_model_reference, prompt_version_reference=EXCLUDED.prompt_version_reference, current_task=EXCLUDED.current_task, queue_count=EXCLUDED.queue_count, success_rate=EXCLUDED.success_rate, notes=EXCLUDED.notes, is_active=EXCLUDED.is_active;